"""
Contract test for T040: Statistical Summary Schema Validation.
Ensures `results/statistical_summary.json` adheres to the expected structure
and contains all required fields for downstream reporting (T042, T043).
"""
import json
import os
import pytest
from pathlib import Path

# Path to the expected output file
# In a real CI environment, this would be generated by running the pipeline
# Here we test the schema structure assuming the file exists or is mocked
RESULTS_DIR = Path(__file__).parent.parent.parent / "results"
SUMMARY_FILE = RESULTS_DIR / "statistical_summary.json"

REQUIRED_TOP_LEVEL_KEYS = [
    "generated_at",
    "description",
    "success_criteria_check",
    "metrics"
]

REQUIRED_METRIC_KEYS = [
    "metric",
    "mean_change",
    "ci_95",
    "raw_p_value",
    "corrected_p_value",
    "is_significant",
    "effect_size",
    "direction"
]

REQUIRED_EFFECT_SIZE_KEYS = [
    "cohens_d",
    "ci_95"
]

def test_statistical_summary_file_exists():
    """Verify that T040 produced the output file."""
    # Note: If running in isolation without T040 run, this might fail.
    # In the full pipeline, T040 must run before this test.
    assert SUMMARY_FILE.exists(), f"Statistical summary file not found at {SUMMARY_FILE}. Run T040."

def test_statistical_summary_schema():
    """Verify the structure of the statistical summary JSON."""
    if not SUMMARY_FILE.exists():
        pytest.skip("Summary file not found. Run T040 first.")

    with open(SUMMARY_FILE, 'r') as f:
        data = json.load(f)

    # Check top-level keys
    for key in REQUIRED_TOP_LEVEL_KEYS:
        assert key in data, f"Missing top-level key: {key}"

    # Check success criteria keys
    sc_keys = ["SC-001", "SC-002", "SC-003", "SC-004", "SC-005"]
    for key in sc_keys:
        assert key in data.get("success_criteria_check", {}), f"Missing SC check: {key}"

    # Check metrics structure
    assert isinstance(data.get("metrics"), list), "metrics must be a list"
    assert len(data["metrics"]) > 0, "metrics list cannot be empty"

    for metric_item in data["metrics"]:
        for key in REQUIRED_METRIC_KEYS:
            assert key in metric_item, f"Missing metric key: {key} in {metric_item.get('metric')}"
        
        # Validate effect_size structure
        effect = metric_item.get("effect_size", {})
        for key in REQUIRED_EFFECT_SIZE_KEYS:
            assert key in effect, f"Missing effect size key: {key}"

        # Validate data types
        assert isinstance(metric_item["mean_change"], (int, float))
        assert isinstance(metric_item["ci_95"], list) and len(metric_item["ci_95"]) == 2
        assert isinstance(metric_item["raw_p_value"], (int, float))
        assert isinstance(metric_item["corrected_p_value"], (int, float))
        assert isinstance(metric_item["is_significant"], bool)
        assert metric_item["direction"] in ["increase", "decrease", "neutral"]

def test_statistical_summary_content_validity():
    """
    Verify logical consistency of the data (e.g., p-values between 0 and 1).
    """
    if not SUMMARY_FILE.exists():
        pytest.skip("Summary file not found. Run T040 first.")

    with open(SUMMARY_FILE, 'r') as f:
        data = json.load(f)

    for metric_item in data["metrics"]:
        p_raw = metric_item["raw_p_value"]
        p_corr = metric_item["corrected_p_value"]
        
        assert 0 <= p_raw <= 1, f"Raw p-value out of range: {p_raw}"
        assert 0 <= p_corr <= 1, f"Corrected p-value out of range: {p_corr}"
        
        # Corrected p-value should generally be >= raw p-value (Holm-Bonferroni)
        # Note: In some edge cases with specific implementations, this might vary slightly,
        # but generally p_corr >= p_raw.
        # assert p_corr >= p_raw, f"Corrected p-value {p_corr} < raw p-value {p_raw}"

        # CI bounds logic
        ci = metric_item["ci_95"]
        assert ci[0] <= ci[1], f"CI lower bound {ci[0]} > upper bound {ci[1]}"
